const storedLocale = typeof window === 'undefined' ? null : window.localStorage.getItem('ccps-locale');
export const i18n = createI18n({ legacy: false, globalInjection: true, locale: supportedLocales.some((item) => item.code === storedLocale) ? storedLocale : 'zh-CN', fallbackLocale: 'zh-CN', messages });

export const setLocale = (locale) => {
  if (!supportedLocales.some((item) => item.code === locale)) return;
  i18n.global.locale.value = locale;
  if (typeof window !== 'undefined') {
    window.localStorage.setItem('ccps-locale', locale);
    document.documentElement.lang = locale;
  }
};

if (typeof document !== 'undefined') document.documentElement.lang = i18n.global.locale.value;
